#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998244353LL;
    long long value;

    Mod998() : value(0) {}
    Mod998(long long v) : value((v % MOD + MOD) % MOD) {}

    static long long modinv(long long a, long long m = MOD) {
        long long m0 = m, t, q;
        long long x0 = 0, x1 = 1;
        if (m == 1) return 0;
        while (a > 1) {
            q = a / m;
            t = m;
            m = a % m; a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }
        if (x1 < 0) x1 += m0;
        return x1;
    }

    static long long nCr(long long n, long long r, vector<long long>& fact, vector<long long>& invFact) {
        if (r > n || r < 0) return 0;
        return (fact[n] * ((invFact[r] * invFact[n - r]) % MOD)) % MOD;
    }

    static void precomputeFactorials(int maxN, vector<long long>& fact, vector<long long>& invFact) {
        fact.resize(maxN + 1);
        invFact.resize(maxN + 1);
        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        invFact[maxN] = modinv(fact[maxN], MOD);
        for (int i = maxN - 1; i >= 0; i--) {
            invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
        }
    }

    Mod998 operator+(const Mod998& other) const {
        return Mod998((value + other.value) % MOD);
    }

    Mod998 operator-(const Mod998& other) const {
        return Mod998((value - other.value + MOD) % MOD);
    }

    Mod998 operator*(const Mod998& other) const {
        return Mod998((value * other.value) % MOD);
    }

    Mod998 inv() const {
        return Mod998(modinv(value, MOD));
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    int maxN = n + m;
    vector<long long> fact, invFact;
    Mod998::precomputeFactorials(maxN, fact, invFact);

    // Compute modular inverse of (n + m)
    long long denom = n + m;
    long long denomInv = Mod998::modinv(denom, Mod998::MOD);

    // Compute phaseSize
    Mod998 phaseSize(1);
    Mod998 p(1);
    for (int i = 0; ; i++) {
        long long numerator = n - i;
        long long denominator = n + m - i;
        if (denominator == 0) break;
        Mod998 mult1(numerator);
        Mod998 invDenominator(denominator);
        p = p * mult1 * invDenominator.inv();
        phaseSize = phaseSize + p;
        if (p.value == 0) break; // To prevent infinite loop if p becomes zero
    }

    Mod998 answer(0);
    for (int k = 1; k <= n; k++) {
        long long numerator = m + k;
        long long denominator = k;
        Mod998 numPhases(numerator);
        Mod998 invK(denominator);
        numPhases = numPhases * invK;

        Mod998 e = numPhases * phaseSize;

        long long comb = Mod998::nCr(n, k, fact, invFact);
        Mod998 term = Mod998(comb) * e;

        if (k % 2 == 1)
            answer = answer + term;
        else
            answer = answer - term;
    }

    cout << answer.value << "\n";

    return 0;
}

